<?php
$n = trim(fgets(STDIN));
$s = trim(fgets(STDIN));
$arr = str_split($s);
$count = 0;
for ($c = 25; $c >= 1; $c--) {
    $ch = chr(ord('a') + $c);
    $prev = chr(ord('a') + $c - 1);
    $changed = true;
    while ($changed) {
        $changed = false;
        $len = count($arr);
        for ($i = 0; $i < $len; $i++) {
            if ($arr[$i] === $ch) {
                if (($i > 0 && $arr[$i-1] === $prev) || ($i < $len-1 && $arr[$i+1] === $prev)) {
                    array_splice($arr, $i, 1);
                    $count++;
                    $changed = true;
                    break;
                }
            }
        }
    }
}
echo $count . "\n";
